def search_products(conn, sort="name", limit=20, **criteria):
    """Return the products matching every criterion (see filters.FILTERABLE), sorted and capped.

    The criteria values come straight from the query string of the catalogue page.
    """
    limit = max(1, min(int(limit), MAX_PAGE))
    where = build_filter(**criteria)
    columns = []
    values = []
    for column, value in sorted(criteria.items()):
        if column not in FILTERABLE:
            raise ValueError(f"cannot filter on {column!r}")
        if value is None:
            continue
        columns.append(column)
        values.append(value)
    cur = conn.execute(
        "SELECT id, name, category, supplier, price_cents FROM products{}{} LIMIT {}".format(where, order_clause(sort), limit)
    )
    return cur.fetchall()

