def fetch_preview(url, fetch, resolve=socket.gethostbyname):
    """Return fetch(url) for a public http(s) URL.

    `fetch` performs the HTTP request; `resolve` maps a host name to an IP address.
    """
    parts = urlparse(url)
    if parts.scheme not in ("http", "https") or not parts.hostname:
        raise ValueError("only http(s) URLs can be previewed")

    ip_addr = resolve(parts.hostname)
    try:
        addr_obj = ipaddress.ip_address(ip_addr)
        # Block loopback, link-local, and reserved private ranges
        if addr_obj.is_loopback or addr_obj.is_link_local:
            raise ValueError("URL resolves to a private address")
        # Check for IPv4-mapped IPv6 addresses that resolve to 127.x.x.x
        if isinstance(addr_obj, ipaddress.IPv6Address):
            try:
                ipv4 = addr_obj.ipv4_mapped
                if ipv4.is_loopback or ipv4.is_link_local:
                    raise ValueError("URL resolves to a private address")
            except ValueError:
                pass
    except ValueError:
        pass
    return fetch(url)
